-- Literal DDL extracted from verified commit f2a4344; never generated by current SqliteStore.
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,type TEXT NOT NULL,time TEXT NOT NULL,hash TEXT NOT NULL,json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_nations(event_id TEXT REFERENCES events(id),nation TEXT NOT NULL,PRIMARY KEY(event_id,nation));
CREATE TABLE IF NOT EXISTS event_players(event_id TEXT REFERENCES events(id),player TEXT NOT NULL,PRIMARY KEY(event_id,player));
CREATE INDEX IF NOT EXISTS history_time ON events(time DESC,id);
CREATE INDEX IF NOT EXISTS nation_history ON event_nations(nation,event_id);
CREATE INDEX IF NOT EXISTS player_history ON event_players(player,event_id);
CREATE TABLE IF NOT EXISTS instances(id TEXT PRIMARY KEY,story TEXT NOT NULL,scope TEXT NOT NULL,completed INTEGER NOT NULL,updated TEXT NOT NULL,json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS active_instances ON instances(story,scope,completed);
CREATE INDEX IF NOT EXISTS instance_origin ON instances(story,scope,json_extract(json,'$.definition.version'),json_extract(json,'$.sourceEventId'));
CREATE TABLE IF NOT EXISTS outcomes(id TEXT PRIMARY KEY,status TEXT NOT NULL,json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS outcome_delivery_status ON outcomes(status,id);
CREATE TABLE IF NOT EXISTS facts(owner TEXT NOT NULL,key TEXT NOT NULL,value TEXT NOT NULL,PRIMARY KEY(owner,key));
CREATE TABLE IF NOT EXISTS story_triggers(id TEXT PRIMARY KEY,trigger_key TEXT NOT NULL,event_id TEXT NOT NULL REFERENCES events(id),scope TEXT NOT NULL,story_json TEXT NOT NULL,checked INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS story_trigger_scope ON story_triggers(scope,checked,id);
CREATE INDEX IF NOT EXISTS story_trigger_event ON story_triggers(event_id,id);
CREATE TABLE IF NOT EXISTS story_trigger_receipts(trigger_key TEXT NOT NULL,scope TEXT NOT NULL,PRIMARY KEY(trigger_key,scope));
CREATE TABLE IF NOT EXISTS native_scene_journal(id TEXT PRIMARY KEY,player TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('READY','RUNNING','UNKNOWN','COMPLETED')),revision INTEGER NOT NULL,json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS native_scene_player_status ON native_scene_journal(player,status,id);
CREATE TABLE IF NOT EXISTS story_choice_log(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,instance_id TEXT NOT NULL REFERENCES instances(id),source_event_id TEXT NOT NULL REFERENCES events(id),story_id TEXT NOT NULL,story_version TEXT NOT NULL,node_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('BALLOT','RESOLUTION')),actor_key TEXT NOT NULL,player_id TEXT,nation_id TEXT NOT NULL,scope_key TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),choice_id TEXT NOT NULL,chosen_at TEXT,committed_by TEXT,provenance TEXT NOT NULL CHECK(provenance IN ('LIVE','LEGACY_INSTANCE')),CHECK((kind='BALLOT' AND player_id IS NOT NULL) OR (kind='RESOLUTION' AND player_id IS NULL)),CHECK((provenance='LIVE' AND chosen_at IS NOT NULL AND committed_by IS NOT NULL) OR (provenance='LEGACY_INSTANCE' AND chosen_at IS NULL AND committed_by IS NULL)),UNIQUE(instance_id,node_id,kind,actor_key,revision));
CREATE INDEX IF NOT EXISTS story_choice_player ON story_choice_log(player_id,story_id,story_version,node_id,kind,seq DESC);
CREATE INDEX IF NOT EXISTS story_choice_scope ON story_choice_log(scope_key,story_id,story_version,node_id,kind,seq DESC);
CREATE TABLE IF NOT EXISTS story_nation_vote_log(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,instance_id TEXT NOT NULL REFERENCES instances(id),source_event_id TEXT NOT NULL REFERENCES events(id),story_id TEXT NOT NULL,story_version TEXT NOT NULL,node_id TEXT NOT NULL,nation_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),action TEXT NOT NULL CHECK(action IN ('CAST','CHANGE','WITHDRAW','INVALIDATE')),status TEXT NOT NULL CHECK(status IN ('ACTIVE','WITHDRAWN','INVALIDATED')),choice_id TEXT,actor_id TEXT NOT NULL,actor_nation_id TEXT NOT NULL,changed_at TEXT NOT NULL,checked_at TEXT NOT NULL,authority_evidence TEXT NOT NULL,CHECK((status='ACTIVE' AND choice_id IS NOT NULL AND action IN ('CAST','CHANGE')) OR (status='WITHDRAWN' AND choice_id IS NULL AND action='WITHDRAW') OR (status='INVALIDATED' AND choice_id IS NULL AND action='INVALIDATE')),UNIQUE(instance_id,node_id,nation_id,revision));
CREATE INDEX IF NOT EXISTS story_nation_vote_history ON story_nation_vote_log(nation_id,story_id,story_version,node_id,seq DESC);
CREATE TABLE IF NOT EXISTS story_nation_votes(instance_id TEXT NOT NULL REFERENCES instances(id),node_id TEXT NOT NULL,nation_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),status TEXT NOT NULL CHECK(status IN ('ACTIVE','WITHDRAWN','INVALIDATED')),choice_id TEXT,actor_id TEXT NOT NULL,checked_at TEXT NOT NULL,authority_evidence TEXT NOT NULL,log_seq INTEGER NOT NULL UNIQUE REFERENCES story_nation_vote_log(seq),CHECK((status='ACTIVE' AND choice_id IS NOT NULL) OR (status IN ('WITHDRAWN','INVALIDATED') AND choice_id IS NULL)),PRIMARY KEY(instance_id,node_id,nation_id));
CREATE TABLE IF NOT EXISTS story_nation_actor_bindings(instance_id TEXT NOT NULL REFERENCES instances(id),node_id TEXT NOT NULL,actor_id TEXT NOT NULL,nation_id TEXT NOT NULL,bound_at TEXT NOT NULL,authority_evidence TEXT NOT NULL,PRIMARY KEY(instance_id,node_id,actor_id));
CREATE TABLE IF NOT EXISTS story_nation_resolutions(id TEXT PRIMARY KEY,instance_id TEXT NOT NULL REFERENCES instances(id),source_event_id TEXT NOT NULL REFERENCES events(id),story_id TEXT NOT NULL,story_version TEXT NOT NULL,node_id TEXT NOT NULL,scope_key TEXT NOT NULL,choice_id TEXT NOT NULL,quorum INTEGER NOT NULL CHECK(quorum>0),actor_id TEXT NOT NULL,checked_at TEXT NOT NULL,authority_evidence TEXT NOT NULL,json TEXT NOT NULL,UNIQUE(instance_id,node_id));
CREATE TABLE IF NOT EXISTS quest_gates(id TEXT PRIMARY KEY,instance_id TEXT NOT NULL REFERENCES instances(id),source_event_id TEXT NOT NULL REFERENCES events(id),story_id TEXT NOT NULL,story_version TEXT NOT NULL,story_fingerprint TEXT NOT NULL,scope_key TEXT NOT NULL,node_id TEXT NOT NULL,effect_id TEXT NOT NULL,player_id TEXT NOT NULL,quest_id TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('PLAYER','NATION')),expected_nation_id TEXT NOT NULL,opened_at INTEGER NOT NULL,provider_id TEXT,provider_pinned_at INTEGER,status TEXT NOT NULL CHECK(status IN ('UNSUPPORTED','NOT_STARTED','ADMITTING','ACTIVE','COMMITTED','ABANDONED','FAILED','CONFLICT','UNKNOWN')),accepted_json TEXT,completion_json TEXT,updated_at INTEGER NOT NULL,last_checked_at INTEGER NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),message TEXT NOT NULL,CHECK(updated_at>=opened_at AND last_checked_at>=opened_at),CHECK((provider_id IS NULL AND provider_pinned_at IS NULL) OR (provider_id IS NOT NULL AND provider_pinned_at IS NOT NULL AND provider_pinned_at>=opened_at AND provider_pinned_at<=updated_at)),CHECK(provider_id IS NOT NULL OR accepted_json IS NULL),CHECK((status='COMMITTED' AND accepted_json IS NOT NULL AND completion_json IS NOT NULL AND provider_id IS NOT NULL) OR (status<>'COMMITTED' AND completion_json IS NULL)),UNIQUE(instance_id,node_id,effect_id,player_id));
CREATE INDEX IF NOT EXISTS quest_gate_pending ON quest_gates(status,last_checked_at,updated_at,id);
CREATE INDEX IF NOT EXISTS quest_gate_instance ON quest_gates(instance_id,node_id,effect_id,player_id);
CREATE TABLE IF NOT EXISTS quest_gate_completions(issuer TEXT NOT NULL,completion_id TEXT NOT NULL,run_id TEXT NOT NULL,gate_id TEXT NOT NULL UNIQUE REFERENCES quest_gates(id),provider_id TEXT NOT NULL,proof_hash TEXT NOT NULL,proof_json TEXT NOT NULL,received_at INTEGER NOT NULL,PRIMARY KEY(issuer,completion_id),UNIQUE(issuer,run_id));
CREATE TABLE IF NOT EXISTS event_causes(event_id TEXT PRIMARY KEY REFERENCES events(id),parent_id TEXT REFERENCES events(id),root_id TEXT NOT NULL REFERENCES events(id),depth INTEGER NOT NULL CHECK(depth>=0),story_path TEXT NOT NULL,CHECK((depth=0 AND parent_id IS NULL) OR (depth>0 AND parent_id IS NOT NULL)));
CREATE INDEX IF NOT EXISTS event_causal_root ON event_causes(root_id,depth,event_id);
CREATE TABLE IF NOT EXISTS story_trigger_blocks(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),story TEXT NOT NULL,version TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS story_definitions(story TEXT NOT NULL,version TEXT NOT NULL,fingerprint TEXT NOT NULL CHECK(length(fingerprint)=64 AND fingerprint NOT GLOB '*[^0-9a-f]*'),json TEXT NOT NULL,provenance TEXT NOT NULL,first_seen TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(story,version,fingerprint));
CREATE TABLE IF NOT EXISTS story_definition_formats(story TEXT NOT NULL,version TEXT NOT NULL,fingerprint TEXT NOT NULL,canonical_version INTEGER NOT NULL CHECK(canonical_version IN (1,2)),PRIMARY KEY(story,version,fingerprint),FOREIGN KEY(story,version,fingerprint) REFERENCES story_definitions(story,version,fingerprint));
CREATE TABLE IF NOT EXISTS story_definition_upgrades(story TEXT NOT NULL,version TEXT NOT NULL,from_fingerprint TEXT NOT NULL,from_canonical_version INTEGER NOT NULL CHECK(from_canonical_version=1),to_canonical_version INTEGER NOT NULL CHECK(to_canonical_version=2),to_fingerprint TEXT NOT NULL CHECK(length(to_fingerprint)=64 AND to_fingerprint NOT GLOB '*[^0-9a-f]*'),json TEXT NOT NULL,algorithm TEXT NOT NULL CHECK(algorithm='V1_TO_V2_ADD_PLAYER_VOTE_UNIT'),PRIMARY KEY(story,version,from_fingerprint),FOREIGN KEY(story,version,from_fingerprint) REFERENCES story_definitions(story,version,fingerprint));
PRAGMA user_version=6;
